// Until then, adapt the default to the available screen.
let guideCollapsed = mobileResearchMedia.matches || window.innerHeight <= 500;
let guidePreferenceChosen = false;
function syncGuideDisclosure() {
  $('guidedCardBody').hidden = guideCollapsed;
  $('guidedCard').dataset.collapsed = String(guideCollapsed);
  $('guideToggle').setAttribute('aria-expanded', String(!guideCollapsed));
  $('guideToggle').textContent = guideCollapsed ? 'Show guide' : 'Hide guide';
}
syncGuideDisclosure();
$('guideToggle').onclick = () => {
  guideCollapsed = !guideCollapsed;
  guidePreferenceChosen = true;
  syncGuideDisclosure();
  measureTourCard();
  applyCameraPreset();
  renderScienceOverlay();
  markStageDirty();
};

/** Whether Research currently replaces the stage with its full-screen sheet. */
function mobileResearchActive(drawerOpen) {
  return drawerOpen && mobileResearchMedia.matches;
}

/**
 * Escape closes the object explanation or Research in last-opened order, which
 * the design requires. Either surface can be opened while the other is already
 * open, so neither is unconditionally on top and a boolean will not do: stamp
 * each opening with a monotonic sequence and close the higher one first.
 */
let surfaceOpenSequence = 0;
let pinnedOpenedAt = 0;
let drawerOpenedAt = 0;

let pendingAudienceFrame = null;
let audienceReframePending = false;
function syncAudienceMode() {
  const evidence = state.audienceMode === AUDIENCE_MODES.evidence;
  const drawerOpen = evidence && state.drawer !== 'closed';
  const mobileResearch = mobileResearchActive(drawerOpen);
  const reframe = $('app').dataset.mode !== state.audienceMode
    || $('app').dataset.drawerOpen !== String(drawerOpen)
    || $('app').dataset.mobileResearch !== String(mobileResearch);
  // Read before the dataset is overwritten below, so this sees the transition.
  if (!drawerOpen) drawerOpenedAt = 0;
  else if ($('app').dataset.drawerOpen !== 'true') drawerOpenedAt = ++surfaceOpenSequence;
  $('app').dataset.mode = state.audienceMode;
  $('app').dataset.drawerOpen = String(drawerOpen);
  $('app').dataset.mobileResearch = String(mobileResearch);
  $('panel').setAttribute('aria-hidden', String(!drawerOpen));
  $('audienceEvidence').classList.toggle('on', evidence);
  $('audienceEvidence').setAttribute('aria-pressed', String(evidence));
  $('canvas').inert = mobileResearch;
  audienceReframePending ||= reframe;
  if (pendingAudienceFrame !== null) cancelAnimationFrame(pendingAudienceFrame);
  pendingAudienceFrame = requestAnimationFrame(() => {
    pendingAudienceFrame = null;
    visualization.resize();
    measureTourCard();
    if (audienceReframePending) applyCameraPreset({ animate: false });
    audienceReframePending = false;
    // This callback may land inside a semantic-camera transition started later
    // in the same audience-state update. Treat it as an intermediate frame;
    // markStageDirty below guarantees a strict settled-frame measurement.
    renderScienceOverlay({ transient: true });
    markStageDirty();
  });
}

let evidenceReturnFocus = $('audienceEvidence');

