function measureTourCard() {
  const height = Math.round($('guidedCard').getBoundingClientRect().height);
  if (height > 0) $('app').style.setProperty('--tour-card-h', `${height}px`);
}

function usesStretchComparisonFrame() {
  return state.audienceMode === AUDIENCE_MODES.guided
    && state.storyStep === STRETCH_CHAPTER_ID
    && state.sceneId === 'spring'
    && state.cameraPreset === 'view.titin_hero';
}

function applyChapterVisibility(chapterId) {
  const visibility = story.chapter(chapterId)?.recommended_state?.visibility;
  if (!visibility) return;
  state.showFilamentContext = visibility.show_lattice;
  state.showDomains = visibility.show_domains;
  state.showContextDetail = visibility.show_context_detail;
  state.mirror = visibility.mirror;
  state.rings = visibility.rings;
  syncNeighbourControl(); syncFilamentContextToggle();
}

function applyCameraPreset({ animate = false } = {}) {
  const [kind, name] = state.cameraPreset.split('.');
  // SC-25. Every camera the reader is given lands in the band the chrome leaves
  // free, so the molecule is both legible and reachable. The band is measured, so
  // this is not a Learn-only special case: with no story card on the stage it is
  // simply the space between the header and the primary bar, which is where the
  // model belongs in Explore too.
  const framing = unobscuredFrameOptions({ animate });
  if (kind === 'view') {
    state.view = name; state.closeup = null;
    if (usesStretchComparisonFrame()) {
      visualization.frameStretchSweep(sweepRange.max, framing);
      // The sweep facade defaults to titin_story; this lesson retains its
      // canonical hero preset in the public report and restored URL state.
      visualization.setPresentationState({ camera_preset: state.cameraPreset });
    } else visualization.frame(name, framing);
    syncViews(); syncCloseups(null);
  } else if (kind === 'closeup') {
    state.closeup = name;
    // Only the invariants a close-up genuinely implies. The filaments are what
    // the close-up is framed against, and the M-band relationship needs both
    // half-sarcomeres. The myosin-head/actin-twist layer is a reviewed DEFAULT
    // of whatever selected the close-up, not a property of the camera: re-
    // applying the camera on a mode reframe, a history restore, or a shared
    // link must not switch a layer the reader turned off back on.
    state.showFilamentContext = true;
    if (name === 'mline') state.mirror = true;
    visualization.closeUp(name, framing);
    rebuild();
    syncCloseups(visualization.closeUp(name, { move: false }));
    syncDepictionToggles();
  } else if (kind === 'region') {
    // Camera focus and biological selection are independent URL fields. A
    // chapter may frame a representative region while selecting a component
    // (molecular architecture does exactly that), so applying the camera must
    // not silently replace the chapter's declared target.
    state.closeup = null;
    visualization.focusTitinRegion(name, framing);
    syncRegions(); syncCloseups(null);
  }
  syncViews();
}

function captureChapterViewState() {
  return {
    scale: state.scale,
    context: state.context,
    cameraPreset: state.cameraPreset,
    selectedTarget: state.selectedTarget,
    region: state.region,
    closeup: state.closeup,
    view: state.view,
    showFilamentContext: state.showFilamentContext,
    showDomains: state.showDomains,
    showContextDetail: state.showContextDetail,
    extendedLattice: state.extendedLattice,
    mirror: state.mirror,
    rings: state.rings,
  };

