  // frame so it never claims that withdrawn heads/twist/anchor detail are visible.
  render(report); refreshRegionReadout();
  if (state.closeup) {
    syncCloseups(visualization.closeUp(state.closeup, { move: false }));
  }
}, ({ camera_moving: cameraMoving } = {}) => {
  // Before the early-out: the onboarding pulse is a change to the scene, so a
  // still stage is exactly the state in which it still has to advance.
  const pulsing = stepInspectionPulse(performance.now());
  if (!stageDirty && !cameraMoving && !pulsing) return;
  stageDirty = false;
  renderScienceOverlay({ transient: cameraMoving }); renderObjectOverlay();
});
// Last, so a hint can never appear over a stage that failed to build.
startInspectionOnboarding();

