// user-initiated, stops on any other interaction, and never runs at a speed the
// operating system has been told the user does not want.
//
// Queried live rather than latched at load: a viewer who turns the setting on
// mid-session is asking for it to apply now, not at the next reload.
const prefersReducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function syncSweepControl() {
  if (sweepHandle !== null) return;
  const replay = Number(slider.value) === sweepRange.max;
  $('stagePlay').classList.remove('on');
  $('stagePlay').setAttribute('aria-pressed', 'false');
  $('stagePlay').textContent = replay ? '↻ Replay stretch' : '\u25b6 Stretch';
  $('stagePlay').setAttribute('aria-label', replay
    ? 'Replay stretch: reset to the working-range minimum and stretch again'
    : 'Play a stretch sweep across the working range');
}

function stopSweep({ completed = false, synchronize = true } = {}) {
  if (sweepHandle !== null) cancelAnimationFrame(sweepHandle);
  sweepHandle = null;
  sweepLastFrameAt = null;
  syncSweepControl();
  if (completed) {
    $('objectAnnouncement').textContent = 'Stretch complete at the supported maximum. '
      + 'The full half-sarcomere and I-band bracket remain framed.';
  }
  // Suppressed while the sweep ran; the length it settled on is the one worth
  // putting in the URL.
  if (synchronize) { syncPublicPresentation(); syncUrl(); }
}

function stepSweep(now) {
  const reduced = prefersReducedMotion();
  if (reduced) {
    if (Number(slider.value) !== sweepRange.max) {
      slider.value = String(sweepRange.max); rebuild();
    }
    stopSweep({ completed: true });
    return;
  }
  if (sweepLastFrameAt === null) sweepLastFrameAt = now;
  else {
    // A software-rendered or backgrounded frame can arrive seconds late. Cap
    // each visual step so the demonstration cannot jump from start to finish
    // without ever showing the bracket changing.
    sweepElapsedMs += Math.min(100, Math.max(0, now - sweepLastFrameAt));
    sweepLastFrameAt = now;
  }
  const raw = sweepLength(sweepElapsedMs, {
    minNm: sweepRange.min,
    maxNm: sweepRange.max,
    periodMs: SWEEP.period_ms,
  });
  const value = sweepElapsedMs >= SWEEP.period_ms / 2 ? sweepRange.max : raw;
  if (Number(slider.value) !== value) { slider.value = String(value); rebuild(); }
  if (value === sweepRange.max) { stopSweep({ completed: true }); return; }
  sweepHandle = requestAnimationFrame(stepSweep);
}

// The working range, not the slider's full range: the illustrative 3,000 nm
// reference and the 1,900 nm short state are outside the declared comparison
// interval and must not be swept through as if they were ordinary physiology.
const sweepRange = {
  min: presentation.scope.working_range_nm[0],
  max: presentation.scope.working_range_nm[1],
};

/**
 * The centre of the stage band no chrome is over, measured rather than assumed.
 *
 * SC-24 introduced this for the Stretch demonstration. SC-25 promotes it to every
 * framing path, because the cold open had a worse version of the same problem: at
 * 1280x720 the story card covered the whole I-band, so the PEVK spring the story
 * is about could not be clicked at all — not merely sat low in the frame. The
 * measurement is the honest one either way; only the number of callers changed.
 */
function unobscuredFrameOptions({ animate = false } = {}) {
  const canvasBox = $('canvas').getBoundingClientRect();
  const headerBox = $('stageHeader').getBoundingClientRect();
  const storyCard = $('guidedCard');
  const storyBox = !storyCard.hidden && storyCard.getClientRects().length
    ? storyCard.getBoundingClientRect() : null;
  const safeTop = Math.max(0, headerBox.bottom - canvasBox.top);
  const safeBottom = Math.min(
    canvasBox.height,
    storyBox ? storyBox.top - canvasBox.top : Infinity,
  );
  return {
    animate,
    contentCenterYPx: safeBottom > safeTop
      ? (safeTop + safeBottom) / 2 : canvasBox.height / 2,
  };
}

// A control that cannot do anything says so, rather than looking available and
// then dying inside a frame callback where nothing surfaces the reason.
if (!(sweepRange.min < sweepRange.max)) {
  $('stagePlay').disabled = true;
  $('stagePlay').title = 'The presentation record declares no working-range '
    + 'interval for the sweep to travel';
}
// One place the sweep is toggled from. SC-17's space key calls this rather than
// synthesizing a click on the button, because a page that clicks its own play
// control is indistinguishable from a page that autoplays — which is what
// test/showcase_phase12.test.js reads the source for, and it is right to.
function toggleSweep() {
  if (sweepHandle !== null) { stopSweep(); return; }
  // The keyboard route arrives here directly, so the disabled state has to be
  // enforced here too and not only by the control that displays it.
  if ($('stagePlay').disabled) return;
  const current = Number(slider.value);
  if (current < sweepRange.min || current > sweepRange.max) {
    $('objectAnnouncement').textContent = 'Stretch not started. The current length is outside '
      + `the supported range; use the slider to choose ${sweepRange.min.toLocaleString()} to `
      + `${sweepRange.max.toLocaleString()} nanometres first.`;
    return;
  }
  const needsSpringScene = !sceneMatch(sceneController.scene('spring'), publicSceneState());
  sweepPresentationActive = true;
  stopInspectionPulse();
  if (needsSpringScene) {
    applySemanticScene('spring', { announce: false });
    $('objectAnnouncement').textContent = 'Changed to the Spring scene so the complete '
      + 'half-sarcomere and I-band bracket stay visible during Stretch.';
  }
  // Reset only on an explicit replay at the endpoint. Paused/intermediate
  // lengths and ordinary chapter/URL navigation preserve their current value.
  if (current === sweepRange.max) {
    slider.value = String(sweepRange.min);
    rebuild();
    $('objectAnnouncement').textContent = `Replay reset to ${sweepRange.min.toLocaleString()} nm; `
      + 'stretching again within the model working range.';
  }
  const start = Number(slider.value);
  // The sweep must not outrun its own camera transition. Resolve the semantic
  // Spring action normally, then establish the reviewed maximum-extent frame
  // synchronously before the first length frame is allowed to run.
  visualization.frameStretchSweep(sweepRange.max, unobscuredFrameOptions());
  const periodMs = prefersReducedMotion() ? SWEEP.reduced_motion_period_ms : SWEEP.period_ms;
  sweepElapsedMs = sweepElapsedAtLength(start, {
    minNm: sweepRange.min, maxNm: sweepRange.max, periodMs,
  });
  sweepLastFrameAt = null;
  $('stagePlay').classList.add('on');
  $('stagePlay').setAttribute('aria-pressed', 'true');
  $('stagePlay').textContent = 'Pause';
  $('stagePlay').setAttribute('aria-label', 'Pause the stretch demonstration');
  sweepHandle = requestAnimationFrame(stepSweep);
}
$('stagePlay').onclick = toggleSweep;
slider.addEventListener('pointerdown', stopSweep);
slider.addEventListener('keydown', stopSweep);
// The 3-D surface, not the #canvas container: the container also holds the stage
// bar, so a pointerdown on ▶ Stretch itself would stop the sweep a moment before
// the click that was meant to stop it, and the button could only ever start one.
renderSurface.addEventListener('pointerdown', stopSweep);

$('canvas').addEventListener('keydown', (event) => {
  // Spatial navigation belongs to the focused stage, not its HTML controls.

