  const labels = [...svg.querySelectorAll('text')].flatMap((node) => {
    if (getComputedStyle(node).visibility === 'hidden') return [];
    const box = node.getBoundingClientRect();
    return box.width > 0 && box.height > 0 ? [{ node, box }] : [];
  });
  const name = (node) => node.textContent.trim() || node.className.baseVal || 'unnamed label';
  const findings = [];
  for (const { node, box } of labels) {
    if (box.left < canvas.left - 0.5 || box.right > canvas.right + 0.5
        || box.top < canvas.top - 0.5 || box.bottom > canvas.bottom + 0.5) {
      findings.push(`${name(node)} is outside the canvas`);
    }
    if (overlaps(box, header, 0)) findings.push(`${name(node)} overlaps the stage header`);
    for (const { box: over, name: what } of chrome) {
      if (overlaps(box, over, 0)) findings.push(`${name(node)} is covered by ${what}`);
    }
  }
  for (let index = 0; index < labels.length; index += 1) {
    for (let other = index + 1; other < labels.length; other += 1) {
      if (overlaps(labels[index].box, labels[other].box)) {
        findings.push(`${name(labels[index].node)} overlaps ${name(labels[other].node)}`);
      }
    }
  }
  return findings;
}

/**
 * At compact phone heights there is no honest free stage lane for a floating
 * invitation in the densest beat. Put the same one-time affordance in the Tour
 * card's normal flow; moving it back restores the full floating treatment as
 * soon as the viewport has room.
 */
function syncInspectHintSurface(canvas, compactHeight) {
  const hint = $('inspectHint');
  const inline = compactHeight && !hint.hidden
    && state.audienceMode === AUDIENCE_MODES.guided;
  if (inline) {
    if (hint.parentElement !== $('guidedCardBody')) $('guidedCardBody').prepend(hint);
    $('inspectHintText').textContent = 'Inspect a label';
    hint.dataset.copyVariant = 'inline';
    hint.style.removeProperty('left');
    hint.style.removeProperty('top');
    hint.style.removeProperty('bottom');
    hint.style.removeProperty('visibility');
    return;
