    if (room && y + (compactComparison ? 48 : 20) < (cardBox?.top ?? height - 60)) {
      const group = svgElement('g', { 'data-stretch-comparison': 'true' });
      for (const { id, label, start, end } of spans) {
        group.append(svgElement('path', {
          d: `M ${start.x_px} ${y - 5} V ${y} H ${end.x_px} V ${y - 5}`,
