    // one line is not measured by it. Shown only when the exaggeration is real.
    const illustrative = illustrativeWidthRatio(pxPerNm);
    if (illustrative !== null && height >= STAGE_LAYOUT.compact_stage_height_px) {
      nodes.push(svgElement('text', {
        x: barX, y: barY + 11, 'text-anchor': 'start', class: 'science-label',
      }, `titin line ≈${illustrative}× reading width, not scale`));
    }
  }
  svg.replaceChildren(...nodes);
  const unresolvedLabels = resolveTerminusLabelCollisions(svg, {
    canvas: canvasRect,
    header: stageHeaderRect,
    chrome: chromeObstacles,
  });
  const compactTerminiSuppressed = unresolvedLabels.length > 0
    && height < STAGE_LAYOUT.compact_stage_height_px;
  if (unresolvedLabels.length) {
    if (transient || compactTerminiSuppressed) {
      // The semantic camera can pass through a projection for which the fixed
      // header/card band has no legal label cell. Never paint an overprint:
      // retain the scientific anchor dots, suppress only their movable leaders
      // and targets for that frame, and require the settled frame to resolve.
      for (const id of unresolvedLabels) {
        for (const node of svg.querySelectorAll(
          `[data-terminus-label="${id}"], [data-terminus-leader="${id}"]`,
        )) node.style.visibility = 'hidden';
      }
      if (compactTerminiSuppressed) {
        svg.dataset.terminusLayout = 'suppressed:compact-stage';
      } else {
        svg.dataset.labelLayout = 'pending';
        svg.dataset.labelLayoutDetail = `unplaced termini: ${unresolvedLabels.join(', ')}`;
      }
    }
  }
  if (!(transient && unresolvedLabels.length && !compactTerminiSuppressed)) {
    const layoutFindings = auditPaintedOverlayLayout(svg, {
      canvas: canvasRect,
      header: stageHeaderRect,
      chrome: chromeObstacles,
    });
    if (unresolvedLabels.length && !compactTerminiSuppressed) {
      layoutFindings.unshift(`unplaced termini: ${unresolvedLabels.join(', ')}`);
    }
    svg.dataset.labelLayout = layoutFindings.length ? 'unresolved' : 'resolved';
    svg.dataset.labelLayoutDetail = layoutFindings.join('; ');
  }
  resolveInspectHintPosition(svg, {
    canvas: canvasRect,
    header: stageHeaderRect,
    chrome: chromeObstacles,
  });
}

