    const row = document.createElement('div');
    row.className = 'pipeline-stage';
    row.dataset.stage = stage.id;
    const head = document.createElement('div');
    head.className = 'pipeline-label';
    head.textContent = stage.label;
    // The figure and its unit are separate elements so the stage band can set
    // the figure at display size without stretching the sentence beside it.
    const count = document.createElement('div');
    count.className = 'pipeline-count';
    const figure = document.createElement('span');
    figure.className = 'pipeline-figure';
    figure.textContent = String(stage.count);
    const unit = document.createElement('span');
    unit.className = 'pipeline-unit';
    unit.textContent = ` ${stage.count_label}`;
    count.append(figure, unit);
