function renderPinnedSelection() {
  const annotation = resolvedAnnotation(pinnedPick);
  const inspector = $('objectInspector');
  inspector.hidden = !annotation;
  // A phone cannot hold two full reading cards without one covering the other.
  // The pinned explanation temporarily replaces the Tour card there; closing
  // it reveals the same Tour state because selection does not mutate the Tour.
  $('app').dataset.pinnedInspector = annotation ? 'true' : 'false';
  if (!annotation) {
    $('guidedSelection').hidden = true;
    $('objectInspectorName').textContent = '';
    $('objectInspectorLay').textContent = '';
    $('objectInspectorEvidence').replaceChildren();
    $('researchContext').textContent = 'Inspecting the current titin selection';
    renderSelectedEvidence(null);
    syncAnnotationIndex();
    objectOverlaySignature = null;
    return;
  }
  const claimView = claimViewForAnnotation(annotation);
  $('objectInspectorName').textContent = annotation.label;
  $('objectInspectorLay').textContent = claimView.plain;
  const chip = createEvidenceChip(
    document,
    evidenceLanguage(presentation, annotation.evidence.claim_class),
    // The five-label Guided vocabulary deliberately groups two inference
    // levels. A selected object must still disclose which canonical level it
    // carries, before the reader decides whether to open Research.
    { interactive: true, canonicalDisclosure: true },
  );
  chip.setAttribute('aria-label', `Open Research evidence: ${chip.textContent}`);
  chip.onclick = () => openEvidence(chip, 'evidence');
  $('objectInspectorEvidence').replaceChildren(chip);
  $('researchContext').textContent = `Current target: ${annotation.label}`;
  $('guidedSelection').hidden = false;
  $('guidedSelectionLabel').textContent = `Selected: ${annotation.label}`;
  // The full explanation is in the pinned card; repeating it here made the
  // reader parse the same paragraph twice.
  $('guidedSelectionText').textContent = '';
  renderSelectedEvidence(annotation);
  if (state.drawerTab === 'sources') renderBibliography();
  syncAnnotationIndex();
  const sourceRoute = state.audienceMode === AUDIENCE_MODES.evidence
    ? 'Review Selected structure in the Research Evidence tab for the full claim and exact sources.'
    : 'Open Why we know this in the pinned explanation to review the full claim and exact sources.';
  $('objectAnnouncement').textContent = `${annotation.label}. ${claimView.plain} `
