1	/**
2	 * SC-11 stage composition arithmetic.
3	 *
4	 * Pure functions with no DOM and no Three.js, so the composition rules that
5	 * decide whether a figure reads correctly are unit-testable rather than being
6	 * inferred from a screenshot. The page imports these; it does not restate them.
7	 */
8	
9	/**
10	 * Framing and overlay constants.
11	 *
12	 * `frame_margin_factor` is why the default view stopped looking unfitted: 1.35
13	 * left the structure occupying three quarters of the width in a frame that is
14	 * mostly empty anyway, because a sarcomere is ~2,200 nm long and ~50 nm across.
15	 */
16	export const STAGE_LAYOUT = Object.freeze({
17	  frame_margin_factor: 1.12,
18	  // Declared by the SC-11 plan for a vertical framing bias and deliberately NOT
19	  // consumed. Nothing reads it because a fixed bias is the wrong shape for the
20	  // problem: how far the model should sit above centre depends on whether the
21	  // guided chapter card is on the stage, and Evidence mode, which has no card,
22	  // wants it centred. Kept as the declared value so a later task that solves
23	  // that properly has the plan's number to start from.
24	  vertical_bias_fraction: 0.08,
25	  min_region_view_span_nm: 140,
26	  bracket_lane_gap_px: 18,
27	  bracket_drop_tick_px: 8,
28	  card_gap_px: 24,
29	  edge_padding_px: 8,
30	  // Height of the stage's bottom rule, where the ruler and the orbit hint live.
31	  scale_bar_baseline_px: 42,
32	  // The reading-width disclaimer is painted below the ruler baseline. Reserve
33	  // its 12 px glyph box plus breathing room when the ruler moves above a card.
34	  scale_caption_below_px: 18,
35	  // Horizontal room one band label needs to itself. With the shipped 12 px
36	  // semibold .science-label style, the widest bracket label measures ~83 px
37	  // including its halo stroke. The 96 px budget retains 13 px of headroom.
38	  // Two labels closer than this collide, which is the case this rule prevents.
39	  label_box_px: 96,
40	  // The full locator end labels need this rail width in Firefox, the widest of
41	  // the three governed engines. Narrower rails use the compact labels while
42	  // still naming both termini in the same frame.
43	  locator_full_labels_min_px: 410,
44	  // The declared SC-27A release viewports are all at least 720 px tall, and the
45	  // stage canvas is full-height, so every reviewed size clears this threshold.
46	  // Below it — an iPhone SE at 667, a 640 px browser window — the free band
47	  // between the stage header and the Tour card is too short to hold the whole
48	  // scientific rail honestly. That is the supported envelope's lower edge, not
49	  // a defect: inside it the overlay withdraws named secondary labels and moves
50	  // the first-use invitation into the card rather than overprinting the ruler.
51	  compact_stage_height_px: 700,
52	  // Browser text boxes can touch by a couple of pixels even when their ink is
53	  // separated by the scale rule (Firefox is the tallest governed engine). A
54	  // larger overlap on both axes is an actual overprint and must be resolved.
55	  label_collision_tolerance_px: 3,
56	  // Terminus labels stay near their projected anchors. This one-line increment
57	  // seeds the rendered-edge search with nearby horizontal and vertical options.
58	  terminus_label_shift_step_px: 18,
59	});
60	
61	/** Viewport classes the reviewed attention budget distinguishes. */
62	const BUDGET_KEY = Object.freeze({
63	  desktop: 'guided_secondary_context_labels_desktop_max',
64	  mobile: 'guided_secondary_context_labels_mobile_max',
65	});
66	
67	/** Vertical offsets of the three bracket lanes, measured down from the lane origin. */
68	export const BRACKET_LANE_OFFSETS = Object.freeze({ major: 0, minor: 24, marker: 45 });
69	
70	const LANE_STACK_PX = BRACKET_LANE_OFFSETS.marker;
71	
72	/**
73	 * Y coordinate of the topmost bracket lane, in container-local CSS pixels.
74	 *
75	 * Anchored to the projected model rather than to the page header, so the labels
76	 * stay attached to the thing they measure at every camera distance.
77	 *
78	 * @param {Array<{y_px:number, visible:boolean}>} projected
79	 * @param {{canvasHeight:number, safeTopPx:number}} opts
80	 * @returns {number}
81	 */
82	export function bracketLaneY(projected, { canvasHeight, safeTopPx }) {
83	  const tops = (projected || [])
84	    .filter((point) => point && point.visible && Number.isFinite(point.y_px))
85	    .map((point) => point.y_px);
86	  if (!tops.length) return safeTopPx + STAGE_LAYOUT.bracket_lane_gap_px;
87	  const modelTop = Math.min(...tops);
88	  const lane = modelTop - STAGE_LAYOUT.bracket_lane_gap_px - LANE_STACK_PX;
89	  const floor = Math.max(safeTopPx, 0);
90	  const ceiling = Math.max(floor, canvasHeight - LANE_STACK_PX - 24);
91	  return Math.max(floor, Math.min(lane, ceiling));
92	}
93	
94	/**
95	 * The labels a guided frame is allowed to draw, in priority order.
96	 *
97	 * `data/showcase_claims.json` has declared an attention budget since SC-0 and
98	 * `scripts/validate_showcase_claims.py` pins it byte-for-byte — but nothing ever
99	 * checked the RENDER against it, and Guided mode drew all six band brackets at
100	 * every viewport. At 375 px they stacked into three overlapping rows and the
101	 * last one clipped off the right edge. A reviewed declaration the product
102	 * ignores is worse than no declaration.
103	 *
104	 * The budget is READ from that record and never restated here, so this function
105	 * cannot drift from the reviewed numbers and cannot be satisfied by editing a
106	 * constant in the layout module.
107	 *
108	 * Two rules, in the record's own order:
109	 *   1. `label_priority` — keep the highest-priority `n` for the viewport class;
110	 *   2. `occlusion_rule` — "hide a lower-priority label before allowing overlap",
111	 *      so a survivor whose box would collide with an already-kept, higher-
112	 *      priority box is dropped rather than drawn on top of it.
113	 *
114	 * Obstruction of the highlighted titin path, the rule's third clause, is
115	 * prevented by construction rather than here: {@link bracketLaneY} puts the
116	 * whole lane above the projected model.
117	 *
118	 * Evidence mode is deliberately exempt. The budget's own key is
119	 * `guided_secondary_context_labels_*`; Evidence is where a specialist asks for
120	 * everything at once, and clipping it there would be a regression, not a fix.
121	 *
122	 * @template {{id:string, priority:number, x:number, widthPx?:number}} T
123	 * @param {T[]} candidates
124	 * @param {'desktop'|'mobile'} viewportClass derived from the canvas width, not
125	 *   from a media query, so a narrow desktop window is governed like a phone
126	 * @param {Record<string, unknown>} budget `showcaseClaims.attention_budget`
127	 * @param {{audience?: string}} [opts]
128	 * @returns {T[]} the labels to draw, highest priority first
129	 */
130	export function labelBudget(candidates, viewportClass, budget, { audience = 'guided' } = {}) {
131	  const ordered = [...(candidates || [])].sort((a, b) => a.priority - b.priority);
132	  if (audience === 'evidence') return ordered;
133	  const key = BUDGET_KEY[viewportClass];
134	  if (!key) {
135	    throw new Error(
136	      `labelBudget: unknown viewport class '${viewportClass}'; expected `
137	      + `${Object.keys(BUDGET_KEY).join(' or ')}`,
138	    );
139	  }
140	  // Deliberately not Number(): Number(null) is 0, which would turn a missing
141	  // record into a silent "draw nothing" instead of a visible failure.
142	  const declared = budget?.[key];
143	  const max = typeof declared === 'number' ? declared : NaN;
144	  if (!Number.isInteger(max) || max < 0) {
145	    throw new Error(
146	      `labelBudget: the attention budget record has no integer '${key}'; `
147	      + 'refusing to draw an unbounded label set',
148	    );
149	  }
150	  const kept = [];
151	  for (const candidate of ordered) {
152	    if (kept.length >= max) break;
153	    const half = ((candidate.widthPx ?? STAGE_LAYOUT.label_box_px)) / 2;
154	    const collides = kept.some((other) => (
155	      Math.abs(other.x - candidate.x) < half + (other.widthPx ?? STAGE_LAYOUT.label_box_px) / 2
156	    ));
157	    if (!collides) kept.push(candidate);
158	  }
159	  return kept;
160	}
161	
162	/**
163	 * Fraction of the model that has to be in view for band brackets to mean
164	 * anything. Below it a bracket is a line whose ends are both off-screen.
165	 */
166	const BRACKET_LANE_MIN_COVERAGE = 0.5;
167	
168	/**
169	 * Whether the bracket lane should hold band brackets at this camera span.
170	 *
171	 * @param {number|null} cameraSpanNm width of the view, in nanometres
172	 * @param {number|null} modelSpanNm axial extent of the model being labelled
173	 * @returns {boolean}
174	 */
175	export function bracketLaneVisible(cameraSpanNm, modelSpanNm) {
176	  const span = Number(cameraSpanNm);
177	  const model = Number(modelSpanNm);
178	  if (!Number.isFinite(span) || span <= 0 || !Number.isFinite(model) || model <= 0) return false;
179	  return span >= model * BRACKET_LANE_MIN_COVERAGE;
180	}
181	
182	/**
183	 * Where the camera is looking, as a fraction of the whole model.
184	 *
185	 * @param {number|null} cameraSpanNm width of the view, in nanometres
186	 * @param {number|null} cameraCentreNm axial position the camera is looking at
187	 * @param {number|null} modelSpanNm axial extent of the model, from x = 0
188	 * @returns {{from01:number, to01:number, measurable:boolean}}
189	 */
190	export function locatorExtent(cameraSpanNm, cameraCentreNm, modelSpanNm) {
191	  const span = Number(cameraSpanNm);
192	  const centre = Number(cameraCentreNm);
193	  const model = Number(modelSpanNm);
194	  const measurable = Number.isFinite(span) && span > 0
195	    && Number.isFinite(centre) && Number.isFinite(model) && model > 0;
196	  if (!measurable) return { from01: 0, to01: 1, measurable: false };
197	  const clamp01 = (value) => Math.max(0, Math.min(1, value));
198	  return {
199	    from01: clamp01((centre - span / 2) / model),
200	    to01: clamp01((centre + span / 2) / model),
201	    measurable: true,
202	  };
203	}
204	
205	/**
206	 * Single ownership decision for the upper scientific-overlay lane.
207	 *
208	 * Tour keeps its full-sarcomere locator across camera scales. Research has no
209	 * Tour locator, so longitudinal band brackets may occupy the lane when their
210	 * coverage is meaningful. If the stage cannot be measured, the locator refuses
211	 * to guess and the pre-existing bracket fallback remains available.
212	 *
213	 * @param {{audience:string, showBands:boolean, cameraSpanNm:number|null,
214	 *   cameraCentreNm:number|null, modelSpanNm:number|null}} state
215	 * @returns {{bracketsVisible:boolean,
216	 *   locator:{from01:number,to01:number,measurable:boolean,visible:boolean}}}
217	 */
218	export function stageOverlayLane({
219	  audience, showBands, cameraSpanNm, cameraCentreNm, modelSpanNm,
220	}) {
221	  const locator = locatorExtent(cameraSpanNm, cameraCentreNm, modelSpanNm);
222	  const locatorVisible = audience === 'guided' && locator.measurable;
223	  const bracketsVisible = Boolean(showBands) && !locatorVisible
224	    && (!locator.measurable || bracketLaneVisible(cameraSpanNm, modelSpanNm));
225	  return {
226	    bracketsVisible,
227	    locator: { ...locator, visible: locatorVisible },
228	  };
229	}
230	
231	/**
232	 * Screen scale of the stage, in CSS pixels per nanometre.
233	 *
234	 * `viewSpanNm` is the width of the scene at the depth the camera is looking at,
235	 * so this number is a property of the CAMERA and not of anything in the scene.
236	 * That is the whole point. Deriving it instead from how far apart two model
237	 * points land on screen sounds more direct and is wrong: it measures the
238	 * projection of that interval, which collapses as the interval turns toward the
239	 * camera. Down the filament axis that method labelled a 96 px rule
240	 * "50000000000000 µm".
241	 *
242	 * @param {number|null} viewSpanNm scene width at the orbit target, or null
243	 * @param {number} viewportPx canvas width in CSS pixels
244	 * @returns {number|null} null when the stage has no measurable scale
245	 */
246	export function stagePxPerNm(viewSpanNm, viewportPx) {
247	  if (!Number.isFinite(viewSpanNm) || Number(viewSpanNm) <= 0) return null;
248	  if (!Number.isFinite(viewportPx) || viewportPx <= 0) return null;
249	  return viewportPx / Number(viewSpanNm);
250	}
251	
252	/** The 1-2-5 sequence: spans a viewer can hold without doing arithmetic. */
253	const SCALE_BAR_MANTISSAS = Object.freeze([1, 2, 5]);
254	
255	/** `1234 nm` reads worse than `1.234 µm`; the measurement is identical. */
256	function formatSpanNm(nm) {
257	  return nm >= 1000 ? `${Number((nm / 1000).toFixed(3))} µm` : `${Number(nm.toFixed(3))} nm`;
258	}
259	
260	/**
261	 * A round bar span for the current projection, and the length to draw it at.
262	 *
263	 * `px` is `nm * pxPerNm` exactly. That is the whole discipline of the thing, and
264	 * the same one SC-6 applied to the d10 dimension line: the drawn length must BE
265	 * the measurement, not a tidied pixel count carrying a label that claims it.
266	 *
267	 * The largest 1-2-5 span that fits the budget is used. Because that sequence
268	 * never leaves a gap wider than 2.5x, the result is never shorter than 0.4 of
269	 * the budget, so a budget of 100 px or more cannot produce a bar below the 40 px
270	 * readability floor.
271	 *
272	 * @param {number} pxPerNm CSS pixels per nanometre where the bar is measured
273	 * @param {number} maxPx pixel budget for the bar
274	 * @returns {{nm:number, px:number, label:string}}
275	 */
276	export function scaleBar(pxPerNm, maxPx) {
277	  if (!Number.isFinite(pxPerNm) || pxPerNm <= 0 || !Number.isFinite(maxPx) || maxPx <= 0) {
278	    throw new Error(
279	      `scaleBar: expected positive finite inputs, got ${pxPerNm} px/nm and a ${maxPx} px budget`,
280	    );
281	  }
282	  const decade = Math.floor(Math.log10(maxPx / pxPerNm));
283	  let nm = 10 ** (decade - 1);
284	  for (let power = decade - 1; power <= decade + 1; power += 1) {
285	    for (const mantissa of SCALE_BAR_MANTISSAS) {
286	      const candidate = mantissa * 10 ** power;
287	      // Compared in pixels, not nanometres, so the budget cannot be exceeded by
288	      // a rounding error in the division that produced it.
289	      if (candidate * pxPerNm <= maxPx) nm = candidate;
290	    }
291	  }
292	  return { nm, px: nm * pxPerNm, label: formatSpanNm(nm) };
293	}
294	
295	/**
296	 * Where the scale bar can sit without being covered or wandering.
297	 *
298	 * The stage's bottom rule is the conventional home for a ruler, but the guided
299	 * chapter card owns the bottom-left corner and its height is set by the
300	 * chapter's copy — chapter 7's pipeline card is several times the height of
301	 * chapter 1's. Placing the bar simply above the card therefore made it jump
302	 * vertically on every Next, which is exactly the wrong behaviour for the one
303	 * thing on screen a viewer uses as a fixed reference.
304	 *
305	 * So: the bottom rule, beside the card when the bar fits there; only when it
306	 * does not — a phone, where the card is nearly the full width — does the bar
307	 * move above the card, and never under the page header.
308	 *
309	 * SC-12 added the stage control bar along that same bottom rule, so the rule is
310	 * no longer at a fixed height: `bottomInsetPx` is how much of the stage the bar
311	 * occupies, measured in the page rather than assumed here, because the bar wraps
312	 * to more rows as the viewport narrows. It defaults to the bare stage's own
313	 * baseline, so a caller with no bar — and every existing test — is unaffected.
314	 *
315	 * @param {{
316	 *   barPx: number,
317	 *   canvas: {width:number, height:number},
318	 *   card: {top:number, right:number, bottom:number}|null,
319	 *   safeTopPx: number,
320	 *   bottomInsetPx?: number,
321	 * }} opts
322	 * @returns {{left:number, baseline:number}} container-local CSS pixels
323	 */
324	export function scaleBarPlacement({
325	  barPx, canvas, card, safeTopPx, bottomInsetPx = STAGE_LAYOUT.scale_bar_baseline_px,
326	}) {
327	  const pad = STAGE_LAYOUT.edge_padding_px + 4;
328	  const inset = Number.isFinite(bottomInsetPx) && bottomInsetPx > 0
329	    ? bottomInsetPx : STAGE_LAYOUT.scale_bar_baseline_px;
330	  const baseline = canvas.height - inset;
331	  if (!card || card.bottom <= baseline - pad) return { left: pad, baseline };
332	  const beside = card.right + pad;
333	  if (beside + barPx <= canvas.width - pad) return { left: beside, baseline };
334	  return {
335	    left: pad,
336	    baseline: Math.max(
337	      safeTopPx + 20,
338	      card.top - pad - STAGE_LAYOUT.scale_caption_below_px,
339	    ),
340	  };
341	}
342	
343	/** Overlap area of two container-local rectangles, in square pixels. */
344	function overlapArea(a, b) {
345	  const width = Math.min(a.right, b.right) - Math.max(a.left, b.left);
346	  const height = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
347	  return width > 0 && height > 0 ? width * height : 0;
348	}
349	
350	/**
351	 * Place a pinned explanation card so it covers neither its own anchor nor any
352	 * control.
353	 *
354	 * SC-11 gave this one job: do not cover the object being explained. SC-25 adds
355	 * the other half of the same rule, because a card that lands on the primary
356	 * controls is a card that swallows the clicks meant for them — it has pointer
357	 * events, so "visually on top" and "functionally in the way" are the same thing
358	 * here. Obstacles are passed in as measured rectangles rather than assumed: the
359	 * story card height is set by the chapter's copy and a phone adds safe-area
360	 * insets, so no constant
361	 * in this module could describe where the free space actually is.
362	 *
363	 * The search is deliberately small and total: four placements around the anchor,
364	 * each clamped into the safe band, scored by how much control area they would
365	 * cover. A zero-collision placement wins outright; when the stage genuinely has
366	 * no room, the least-bad placement is returned WITH what it collides with, so the
367	 * caller can report a real constraint instead of silently painting over a button.
368	 *
369	 * @param {{
370	 *   anchor: {x_px:number, y_px:number},
371	 *   card: {width:number, height:number},
372	 *   canvas: {width:number, height:number},
373	 *   safeTopPx: number,
374	 *   gapPx?: number,
375	 *   safeBottomPx?: number,
376	 *   safeLeftPx?: number,
377	 *   safeRightPx?: number,
378	 *   obstacles?: Array<{id:string, left:number, top:number, right:number, bottom:number}>,
379	 * }} opts
380	 * @returns {{left:number, top:number, side:'left'|'right', overlaps_anchor:boolean,
381	 *   collides_with:string[], collision_area_px:number}}
382	 */
383	export function inspectorPlacement({
384	  anchor, card, canvas, safeTopPx, gapPx = STAGE_LAYOUT.card_gap_px,
385	  safeBottomPx = 0, safeLeftPx = 0, safeRightPx = 0, obstacles = [],
386	}) {
387	  const pad = STAGE_LAYOUT.edge_padding_px;
388	  const minLeft = pad + safeLeftPx;
389	  const maxLeft = canvas.width - card.width - pad - safeRightPx;
390	  const minTop = safeTopPx;
391	  const maxTop = canvas.height - card.height - pad - safeBottomPx;
392	  const clampLeft = (value) => Math.max(minLeft, Math.min(maxLeft, value));
393	  const clampTop = (value) => Math.max(minTop, Math.min(maxTop, value));
394	  const toLeft = anchor.x_px - card.width - gapPx;
395	  const toRight = anchor.x_px + gapPx;
396	  const fits = (left) => left >= minLeft && left <= maxLeft;
397	  // Prefer the side with more room; fall back to the other before clamping, so
398	  // a clamp is the last resort rather than the first behaviour.
399	  const preferredX = anchor.x_px > canvas.width / 2 ? toLeft : toRight;
400	  const alternateX = preferredX === toLeft ? toRight : toLeft;
401	  const beside = fits(preferredX) ? preferredX : (fits(alternateX) ? alternateX : preferredX);
402	  const centredY = anchor.y_px - card.height / 2;
403	  const otherSide = preferredX === toLeft ? toRight : toLeft;
404	  // Beside the anchor and vertically centred on it is the SC-11 placement and
405	  // stays first, because it keeps the explanation next to the thing explained.
406	  // The rest are escapes, in decreasing order of how well they keep that
407	  // relationship: the same side higher or lower, then the other side, then
408	  // directly above or below. The list is fixed and short so the result is
409	  // reproducible and cheap; nothing here searches.
410	  const candidates = [
411	    { left: beside, top: centredY },
412	    { left: beside, top: minTop },
413	    { left: beside, top: maxTop },
414	    { left: otherSide, top: centredY },
415	    { left: otherSide, top: minTop },
416	    { left: otherSide, top: maxTop },
417	    { left: anchor.x_px - card.width / 2, top: anchor.y_px - card.height - gapPx },
418	    { left: anchor.x_px - card.width / 2, top: anchor.y_px + gapPx },
419	  ];
420	  // Then the escapes past each obstacle in turn. A stage whose story card is half
421	  // its width leaves no anchor-relative placement clear of it, and the answer to
422	  // "the only free space is beyond that edge" has to be expressed as that edge —
423	  // the alternative is a card that lands on the chapter's own Next button.
424	  //
425	  // Ordered by how far each would sit from the anchor, NOT by the order the
426	  // obstacles happened to arrive in. Both matter and only one is meaningful: the
427	  // header's escape and the story card's escape are equally legal, and taking
428	  // whichever was listed first parks the explanation in a far corner while a
429	  // clear placement beside its molecule goes unused.
430	  //
431	  // Both axes are crossed rather than varied one at a time. Varying only one
432	  // holds the other at its anchor-relative value, so a stage whose free space
433	  // is diagonally offset from the anchor — the common case once the painted
434	  // scientific labels are obstacles too — has no candidate at all in the clear
435	  // region, and the scorer settles for the least-bad overlap instead of the
436	  // placement that overlaps nothing.
437	  const escapeX = [beside, otherSide];
438	  const escapeY = [centredY];
439	  for (const obstacle of obstacles) {
440	    escapeX.push(obstacle.right + gapPx, obstacle.left - card.width - gapPx);
441	    escapeY.push(obstacle.bottom + gapPx, obstacle.top - card.height - gapPx);
442	  }
443	  const escapes = [];
444	  for (const left of escapeX) {
445	    for (const top of escapeY) escapes.push({ left, top });
446	  }
447	  const anchorDistance = (candidate) => Math.hypot(
448	    clampLeft(candidate.left) + card.width / 2 - anchor.x_px,
449	    clampTop(candidate.top) + card.height / 2 - anchor.y_px,
450	  );
451	  escapes.sort((a, b) => anchorDistance(a) - anchorDistance(b));
452	  candidates.push(...escapes);
453	  /** @type {{left:number, top:number, collides_with:string[], area:number,
454	   *   coversAnchor:boolean}|null} */
455	  let chosen = null;
456	  for (const candidate of candidates) {
457	    const left = clampLeft(candidate.left);
458	    const top = clampTop(candidate.top);
459	    const box = { left, top, right: left + card.width, bottom: top + card.height };
460	    const hit = obstacles.filter((obstacle) => overlapArea(box, obstacle) > 0);
461	    const area = hit.reduce((sum, obstacle) => sum + overlapArea(box, obstacle), 0);
462	    const coversAnchor = anchor.x_px >= left && anchor.x_px <= left + card.width
463	      && anchor.y_px >= top && anchor.y_px <= top + card.height;
464	    const row = {
465	      left, top, area, coversAnchor,
466	      collides_with: hit.map((obstacle) => obstacle.id),
467	    };
468	    // Lexicographic, not a weighted sum, so no arbitrary exchange rate decides
469	    // whether covering a control is worth being nearer the anchor: never cover the
470	    // object being explained; then cover as little chrome as possible; then keep
471	    // the list's own order, which is the SC-11 preference for the side away from
472	    // the anchor followed by the escapes, nearest first. The anchor is scored
473	    // rather than vetoed, because a stage with no clear placement must still
474	    // answer.
475	    const better = !chosen
476	      || (row.coversAnchor !== chosen.coversAnchor ? !row.coversAnchor
477	        : row.area < chosen.area);
478	    if (better) chosen = row;
479	    if (!row.coversAnchor && row.area === 0) break;
480	  }
481	  if (!chosen) throw new Error('inspectorPlacement: no candidate placement was scored.');
482	  const placed = chosen;
483	  return {
484	    left: placed.left,
485	    top: placed.top,
486	    side: /** @type {'left'|'right'} */ (placed.left > anchor.x_px ? 'right' : 'left'),
487	    overlaps_anchor: placed.coversAnchor,
488	    collides_with: placed.collides_with,
489	    collision_area_px: placed.area,
490	  };
491	}
