// Below the governed compact-stage threshold, and therefore outside the six
// declared release viewports, which are all at least 720 px tall. The overlay
// may withdraw named secondary labels here; it may never overprint, and the
// first-use invitation must still reach the reader.
const COMPACT_HEIGHT_VIEWPORTS = [
  { width: 375, height: 667 },
  { width: 390, height: 684 },
  { width: 360, height: 640 },
];

test('SC27A compact-height coverage sits below the declared release envelope', () => {
  for (const { height } of COMPACT_HEIGHT_VIEWPORTS) {
    expect(height).toBeLessThan(STAGE_LAYOUT.compact_stage_height_px);
  }
  for (const { height } of SC27A_VIEWPORTS) {
    expect(height).toBeGreaterThanOrEqual(STAGE_LAYOUT.compact_stage_height_px);
  }
});

for (const viewport of COMPACT_HEIGHT_VIEWPORTS) {
  test(`SC27A compact-height inspection guidance remains visible at ${viewport.width}x${viewport.height}`,
    async ({ page }) => {
      await page.setViewportSize(viewport);
      await setReducedMotion(page, true);
      for (const [index, beat] of SC27A_BEATS.entries()) {
        await page.goto(`/#v=2&depth=learn&step=${beat}`
          + '&sl=2200&drawer=closed&scene=overview&confidence=0');
        await waitForReady(page);
        const overlay = page.locator('#scienceOverlay');
        await expect.poll(() => overlay.getAttribute('data-label-layout'))
          .toMatch(/^(resolved|suppressed:compact-stage)$/);
        const labelLayout = await overlay.getAttribute('data-label-layout');
        await expect(overlay).toHaveAttribute(
          'data-terminus-layout', /^(resolved|suppressed:compact-stage)$/,
        );
        if (labelLayout === 'suppressed:compact-stage') {
          await expect(overlay.locator('text')).toHaveCount(0);
        }
        await expect(page.locator('#inspectHint')).toBeVisible();
        await expect(page.locator('#inspectHint')).toHaveAttribute('data-overlay-layout', 'resolved');
        await expect(page.locator('#inspectHint')).toHaveAttribute(
          'data-copy-variant', /^(full|compact|minimal|inline)$/,
        );
        await expect(page.locator('#chapterProgress')).toHaveText(`Beat ${index + 1} of 5`);
      }
    });
}

